#!/usr/bin/env node
// SC-06 – Secure development life-cycle: SBOM per release, vulnerability thresholds and signed artefacts
// (IEC 81001-5-1 §5–§8, FDA §524B, NIST SA-11 / SR-4).
//   * CycloneDX SBOM of the build exists (generated by the existing Maven plugin) and lists components;
//   * vulnerability scan: OWASP dependency-check (Maven -Psecurity) when NVD_API_KEY is available, failing at CVSS ≥ 7;
//   * signed driver packages: a package signed by the platform key verifies; a TAMPERED copy and an UNSIGNED copy are rejected;
//   * the SBOM is recorded at the core (GET /device-security/sdlc shows it).
import { existsSync, readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import { Result, bearer, http, parseArgs, sha256 } from './lib/pack.mjs';

const SCRIPT = '07_sbom_and_vuln_scan';
const args = parseArgs(`${SCRIPT}.mjs`, 'SBOM, dependency vulnerability scan and driver-package signature verification.');
const cfg = args.config;
const r = new Result(SCRIPT, ['SC-06'], cfg.environment);
const repo = cfg.repoRoot || process.cwd();

function findBoms(dir, depth = 0, out = []) {
  if (depth > 4 || !existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    if (name === 'node_modules' || name.startsWith('.')) continue;
    const p = join(dir, name);
    if (statSync(p).isDirectory()) findBoms(p, depth + 1, out);
    else if (/^(bom|.*cyclonedx.*)\.json$/i.test(name) && p.includes('target')) out.push(p);
  }
  return out;
}

if (args.extra['build-sbom']) {
  const b = spawnSync(join(repo, 'mvnw'), ['-q', '-o', '-DskipTests', 'verify'], { cwd: repo, encoding: 'utf8', timeout: 1800000 });
  r.expect('sbom-build', 'build with CycloneDX SBOM generation', b.status === 0, `exit ${b.status}`);
}
const boms = findBoms(repo);
if (boms.length === 0) {
  r.notRun('sbom', 'CycloneDX SBOM per release', 'no target/bom.json found – run with --build-sbom or after mvn verify');
} else {
  for (const f of boms.slice(0, 20)) {
    let ok = false;
    let detail;
    try {
      const j = JSON.parse(readFileSync(f, 'utf8'));
      ok = j.bomFormat === 'CycloneDX' && Array.isArray(j.components) && j.components.length > 0;
      detail = `${j.components?.length ?? 0} components, sha256 ${sha256(readFileSync(f))}`;
    } catch (e) {
      detail = 'unreadable';
    }
    r.expect(`sbom:${f.replace(repo, '.')}`, 'CycloneDX SBOM with components', ok, detail);
  }
}

if (process.env.NVD_API_KEY && args.extra['dependency-check']) {
  const d = spawnSync(join(repo, 'mvnw'), ['-q', '-Psecurity', '-DskipTests', 'verify'], { cwd: repo, encoding: 'utf8', timeout: 3600000 });
  r.expect('dependency-check', 'no dependency with CVSS ≥ 7 (OWASP dependency-check) and 0 SpotBugs findings', d.status === 0, `exit ${d.status}`);
} else {
  r.notRun('dependency-check', 'dependency vulnerability scan (CVSS ≥ 7 fails)', 'needs NVD_API_KEY and --dependency-check');
}

const tester = cfg.integrationTesterBearer;
if (cfg.apiBase && tester) {
  const manifest = {
    schema: 'wellnessz.device-driver/1', packageId: 'pack.security.selftest', version: '1.0.0', family: 'VITALS', models: ['MD-027'],
    adapter: 'HL7V2', protocol: { port: 2575, credentialRef: 'devsec:00000000-0000-4000-8000-000000000000' },
    mappings: [{ key: 'HR', loinc: '8867-4', ucum: '/min', factor: 1.50 }],
  };
  const signed = await http('POST', `${cfg.apiBase}/device-security/packages/sign`, { headers: bearer(tester), body: manifest });
  if (signed.status !== 200) {
    r.fail('package-sign', 'platform signs a clean driver package', `HTTP ${signed.status}`);
  } else {
    const pkg = { ...manifest, signature: signed.json.signature };
    const verifier = cfg.secopsBearer || tester;
    const good = await http('POST', `${cfg.apiBase}/device-security/packages/verify`, { headers: bearer(verifier), body: pkg });
    r.expect('package-signed-valid', 'signed package verifies (Ed25519)', good.json?.valid === true, `HTTP ${good.status} ${good.json?.algorithm ?? ''}`);
    const tampered = { ...pkg, mappings: [{ ...manifest.mappings[0], factor: 15.0 }] };
    const bad = await http('POST', `${cfg.apiBase}/device-security/packages/verify`, { headers: bearer(verifier), body: tampered });
    r.expect('package-tampered', 'tampered package rejected (signature_invalid)', bad.json?.valid === false && bad.json?.failureCode === 'signature_invalid',
      `HTTP ${bad.status} ${bad.json?.failureCode ?? ''}`);
    const unsigned = await http('POST', `${cfg.apiBase}/device-security/packages/verify`, { headers: bearer(verifier), body: manifest });
    r.expect('package-unsigned', 'unsigned package rejected (signature_missing)', unsigned.json?.valid === false && unsigned.json?.failureCode === 'signature_missing',
      `HTTP ${unsigned.status} ${unsigned.json?.failureCode ?? ''}`);
    const secret = await http('POST', `${cfg.apiBase}/device-security/packages/sign`, { headers: bearer(tester),
      body: { ...manifest, protocol: { password: 'literal-value-for-test' } } });
    r.expect('package-with-secret', 'package with a literal secret is never signed', secret.status === 422, `HTTP ${secret.status} ${secret.json?.code ?? ''}`);
  }
} else {
  r.notRun('package-signatures', 'driver-package signatures', 'apiBase and integrationTesterBearer are required');
}
if (cfg.apiBase && cfg.secopsBearer) {
  const sdlc = await http('GET', `${cfg.apiBase}/device-security/sdlc`, { headers: bearer(cfg.secopsBearer) });
  r.expect('sbom-recorded', 'SBOM of the release recorded at the core', sdlc.status === 200 && !!sdlc.json?.sbom?.documentId,
    sdlc.json?.sbom ? `${sdlc.json.sbom.release} ${sdlc.json.sbom.format}` : `HTTP ${sdlc.status}`);
  const overdue = (sdlc.json?.vulnerabilities ?? []).filter((v) => v.overdue && ['CRITICAL', 'HIGH'].includes(v.severity));
  r.expect('remediation-sla', 'no critical (7 d) / high (30 d) vulnerability past its due date', sdlc.status === 200 && overdue.length === 0,
    `${overdue.length} overdue`);
}
r.write(args.out);
